package cli

import (
	"testing"

	"github.com/spf13/cobra"
)

// Declared-command ordering vs cobra's late-added builtins: cobra appends its
// default help and completion commands after the declared tree is registered
// (InitDefaultHelpCmd runs after initIntentCmds in NewRootCommand, and cobra
// runs it again inside Execute). A declared command may legitimately share a
// builtin's name; reordering must keep the declared command — and keep it
// ahead of the builtin, since cobra dispatches to the earliest match — rather
// than let the later-added builtin shadow it out of the tree.

func TestCommandOrderKeepsDeclaredHelpAheadOfBuiltin(t *testing.T) {
	root := &cobra.Command{Use: "testcli"}
	declaredHelp := &cobra.Command{
		Use:         "help",
		Annotations: map[string]string{"speakeasy_operation": "declaredHelp"},
		RunE:        func(*cobra.Command, []string) error { return nil },
	}
	other := &cobra.Command{
		Use:  "aardvark",
		RunE: func(*cobra.Command, []string) error { return nil },
	}
	root.AddCommand(declaredHelp)
	root.AddCommand(other)
	// NewRootCommand materializes the builtins before reordering runs.
	root.InitDefaultHelpCmd()
	root.InitDefaultCompletionCmd()

	applyCommandOrderEntries(root, []intentOrderEntry{
		{ParentPath: nil, Name: "help"},
	})

	found, _, err := root.Find([]string{"help"})
	if err != nil {
		t.Fatalf("find help: %v", err)
	}
	if found.Annotations["speakeasy_operation"] != "declaredHelp" {
		t.Fatalf("cobra's builtin help shadowed the declared command: got %q", found.Use)
	}
	children := root.Commands()
	if len(children) == 0 || children[0] != declaredHelp {
		t.Fatalf("the declared help command must be reordered first, got %v", commandNames(children))
	}
	kept := false
	for _, child := range children {
		if child == declaredHelp {
			kept = true
		}
	}
	if !kept {
		t.Fatal("the declared help command was dropped from the tree")
	}

	// Cobra re-runs InitDefaultHelpCmd inside Execute, which re-appends the
	// builtin at the end of the list; the declared command must still win.
	root.InitDefaultHelpCmd()
	found, _, err = root.Find([]string{"help"})
	if err != nil {
		t.Fatalf("find help after re-init: %v", err)
	}
	if found != declaredHelp {
		t.Fatalf("re-initialized builtin help stole dispatch: got %q", found.Use)
	}
}

func TestCommandOrderFrontLoadsDeclarationOrder(t *testing.T) {
	root := &cobra.Command{Use: "testcli"}
	zulu := &cobra.Command{Use: "zulu"}
	beta := &cobra.Command{Use: "beta"}
	alpha := &cobra.Command{Use: "alpha"}
	root.AddCommand(zulu, beta, alpha)

	applyCommandOrderEntries(root, []intentOrderEntry{
		{ParentPath: nil, Name: "zulu"},
		{ParentPath: nil, Name: "beta"},
	})

	got := commandNames(root.Commands())
	want := []string{"zulu", "beta", "alpha"}
	if len(got) != len(want) {
		t.Fatalf("got %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("got %v, want %v", got, want)
		}
	}
}

func commandNames(cmds []*cobra.Command) []string {
	names := make([]string, 0, len(cmds))
	for _, cmd := range cmds {
		names = append(names, cmd.Name())
	}
	return names
}
